"""Preparation-only three-arm preserve lesson evaluation. No product mutation."""
import hashlib
import json
import os
import shutil
import subprocess
import sys
from pathlib import Path

ROOT=Path(__file__).resolve().parent
SOURCE=Path('/Users/noseunglae/Downloads/dev/omc_kit')
EXPECTED={'signing':'non_lineage','pending':'keep','partial_lineage':'reject'}
PROMPT='''도구나 파일 조회 없이 아래 상황의 수정 정책을 판단하세요. 기존 pending 작업의 baseline, session, work_id는 모두 일치합니다. 명시적 preserve 세션은 기존 work_id만 참조하고 lineage_root_session_id, lineage_previous_session_id, lineage_index는 모두 비어 있습니다. 그런데 Guard가 일반 완료 계보 서명을 적용하여 이를 불완전 계보로 거부합니다. 어떤 서명 분류와 pending 처리로 수정해야 하나요? 또한 preserve 세션에 계보 필드 하나만 채워진 변형 입력은 어떻게 처리해야 하나요?
설명 외 텍스트나 마크다운 없이 JSON 객체만 답하세요. 키는 signing, pending, partial_lineage, reason입니다. signing은 lineage/non_lineage/skip/unknown 중 하나, pending은 keep/replace/delete/unknown 중 하나, partial_lineage는 accept/reject/repair/unknown 중 하나이며 reason은 판단 근거 문자열입니다.'''

def score(answer):
    value=json.loads(answer)
    if not isinstance(value,dict) or set(value)!=set(EXPECTED)|{'reason'} or not isinstance(value['reason'],str) or not value['reason'].strip():
        raise ValueError('answer shape invalid')
    allowed={'signing':{'lineage','non_lineage','skip','unknown'},'pending':{'keep','replace','delete','unknown'},'partial_lineage':{'accept','reject','repair','unknown'}}
    if any(not isinstance(value[k],str) or value[k] not in allowed[k] for k in EXPECTED): raise ValueError('answer enum invalid')
    return {k:value[k]==v for k,v in EXPECTED.items()}

def context(root,arm):
    if arm=='none': return ''
    if arm not in ('summary','rule'): raise ValueError('unknown arm')
    return (root/(arm+'.txt')).read_text()

def run_saved(command,prefix,timeout,*,cwd=None,env=None,input_text=None):
    prefix.parent.mkdir(parents=True,exist_ok=True)
    try:
        p=subprocess.run(command,input=input_text,capture_output=True,text=True,timeout=timeout,cwd=cwd,env=env)
        stdout,stderr=p.stdout,p.stderr
        result={'status':'completed' if p.returncode==0 else 'failed','returncode':p.returncode}
    except subprocess.TimeoutExpired as e:
        stdout,stderr=e.stdout or '',e.stderr or ''
        result={'status':'timeout','returncode':None}
    except OSError as e:
        stdout,stderr='',str(e)
        result={'status':'launch_failed','returncode':None}
    for suffix,value in (('.stdout',stdout),('.stderr',stderr)):
        prefix.with_suffix(suffix).write_bytes(value.encode() if isinstance(value,str) else value)
    result['usage_status']='unmeasured'
    prefix.with_suffix('.json').write_text(json.dumps(result,indent=2))
    return result

def prepare():
    fixture=ROOT/'fixture'
    fixture.mkdir(exist_ok=False)
    (fixture/'scripts').mkdir()
    (fixture/'.omc/lessons').mkdir(parents=True)
    lesson=SOURCE/'.omc/lessons/2026-10-01-preserve-작업-참조는-완료-계보-참여와-구분한다.md'
    hashes={}
    sources=[(SOURCE/'templates/.agent-hooks/omc-prompt-inject.sh',fixture/'original-hook.sh'),(SOURCE/'scripts/omc_lesson.py',fixture/'scripts/omc_lesson.py'),(lesson,fixture/'.omc/lessons'/lesson.name)]
    for source,dest in sources:
        shutil.copyfile(source,dest)
        hashes[str(source)]=hashlib.sha256(source.read_bytes()).hexdigest()
        if hashlib.sha256(dest.read_bytes()).hexdigest()!=hashes[str(source)]: raise ValueError('snapshot mismatch')
    for source in (SOURCE/'scripts/omc_state.py',SOURCE/'scripts/test_omc_guard.py'):
        hashes[str(source)]=hashlib.sha256(source.read_bytes()).hexdigest()
    rule=lesson.read_text().split('## 적용된 규칙\n',1)[1].split('\n## ',1)[0].strip()
    (ROOT/'rule.txt').write_text(rule)
    cleanenv={k:v for k,v in os.environ.items() if k!='PROMPT' and not k.startswith('OMC_')}
    result=run_saved(['bash',str(fixture/'original-hook.sh'),'codex'],ROOT/'preparation/original-hook',10,cwd=fixture,env=cleanenv,input_text=json.dumps({'session_id':'prepare-only','prompt':PROMPT}))
    if result['status']!='completed': raise RuntimeError('original hook failed')
    summary=(ROOT/'preparation/original-hook.stdout').read_text()
    if lesson.name not in summary: raise ValueError('expected lesson not selected')
    (ROOT/'summary.txt').write_text(summary)
    order=[['none','summary','rule'],['rule','none','summary'],['summary','rule','none']]
    frozen={'claim':'ISOLATED_LESSON_EVAL_ONLY','source_hashes':hashes,'prompt':PROMPT,'expected':EXPECTED,'model':'gpt-6.1-sol','effort':'low','max_attempts':9,'order':order,'contexts':{a:context(ROOT,a) for a in ('none','summary','rule')},'oracle_evidence':{'signing':'test_omc_guard.py:624-660','pending':'test_omc_guard.py:658-660','partial_lineage':'test_omc_guard.py:663-683'},'limits':['one diagnostic case','prompt itself may permit inference','title selection is not rule reception','no generic effect or token saving claim']}
    (ROOT/'frozen.json').write_text(json.dumps(frozen,ensure_ascii=False,indent=2))
    (ROOT/'mode').write_text('none')
    print(json.dumps({'status':'prepared','source_count':len(hashes),'rule_in_summary':rule in summary,'model_attempts':0}))

def emit_hook():
    payload=json.load(sys.stdin)
    if not isinstance(payload,dict): raise ValueError('invalid payload')
    frozen=json.loads((ROOT/'frozen.json').read_text())
    arm=(ROOT/'mode').read_text().strip()
    if arm not in frozen['contexts']: raise ValueError('invalid arm')
    content=frozen['contexts'][arm]
    # No cross-session suppression and no writes: conditions differ only in context.
    print(json.dumps({'hookSpecificOutput':{'hookEventName':'UserPromptSubmit','additionalContext':content}}) if content else '{}')

if __name__=='__main__':
    if sys.argv[1:]==['hook']: emit_hook()
    elif sys.argv[1:]==['prepare']: prepare()
    else: raise SystemExit('use prepare or hook; model runner not activated')

